def get_version(path=None, module=None):
    """Return the version information as a string.

    This uses the ``__version__`` variable in the module specified by the
    ``module`` parameter. If this variable is not found, the ``version.txt``
    file is read and the first line is used.

    """
    if path is None:
        path = os.path.dirname(os.path.abspath(__file__))
    if module is None:
        module = __name__
    try:
        return getattr(importlib.import_module(module), '__version__')
    except AttributeError:
        with open(os.path.join(path, 'version.txt'), 'r') as f:
            return f.read().splitlines()[0]


def get_git_revision(path=None, module=None):
    """Return the git revision as a string.

    This uses the ``__git_revision__`` variable in the module specified by the
    ``module`` parameter. If this variable is not found, the ``version.txt``
    file is read and the second line is used.

    """
    if path is None:
        path = os.path.dirname(os.path.abspath(__file__))
    if module is None:
        module = __name__
    try:
        return getattr(importlib.import_module(module), '__git_revision__')
    except AttributeError:
        with open(os.path.join(path, 'version.txt'), 'r') as f:
            return f.read().splitlines()[1]


